(function(){
'use strict';
const A=KopaAnalytics,F=KopaFixtures,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(n,d=0)=>n==null?'—':n.toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d}),money=n=>n==null?'Unavailable':'€'+num(n,2),short=d=>new Date(d+'T00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}),span=w=>short(w.start)+' – '+short(w.end),names={overview:'Overview',keywords:'Keywords',ads:'Apple Ads',experiments:'Experiments',sources:'Sources'},icons={overview:'◫',keywords:'⌁',ads:'↗',experiments:'⊕',sources:'▤'};
const defaults={screen:'keywords',direction:'fieldwork',app:'pois',market:'DE',device:'iphone',range:'28',end:F.END,compare:'previous',selected:'k0,k1',metric:'downloads',query:'',sort:'mean',descending:'false',intent:'all',band:'all',group:'off',pinned:'off',scenario:'normal',attribution:'tap',level:'campaign',parent:''};
let S,chartInfo,hover=-1,brushStart=null,resizeObserver,lastFocus,modalType=null;
function read(){const p=new URLSearchParams(location.search);S={...defaults,...Object.fromEntries(p)};if(!names[S.screen])S.screen='keywords';if(!F.apps.some(a=>a.id===S.app)&&S.app!=='all')S.app='pois';if(!['DE','US'].includes(S.market))S.market='DE';if(!['7','28','90','custom'].includes(S.range))S.range='28';if(!/^2026-\d\d-\d\d$/.test(S.end)||S.end>F.END||S.end<'2026-06-01')S.end=F.END;if(S.range==='custom'&&(!S.start||S.start>S.end))S.range='28';if(!['fieldwork','signal'].includes(S.direction))S.direction='fieldwork';for(const [key,allowed] of Object.entries({device:['iphone','ipad'],level:['campaign','group','keyword','term'],attribution:['tap','view','total'],scenario:['normal','missing','legacy','stale','empty','delay','ambiguous','failed','denied','loading','zero'],compare:['previous','off','custom'],intent:['all','Core intent','Feature','Discovery','Brand'],band:['all','1-1','2-5','6-10','11-20','21-50','51-100']})){if(!allowed.includes(S[key]))S[key]=defaults[key];}for(const key of ['start','brushStart','brushEnd','compareStart','compareEnd'])if(S[key]&&!/^2026-\d\d-\d\d$/.test(S[key]))S[key]='';S.selected=S.selected.split(',').filter(x=>/^k[0-7]$/.test(x)).slice(0,4).join(',');S.sort=S.sort.split(',').filter(x=>['name','mean','latest','movement','coverage'].includes(x)).join(',')||'mean';if(S.brushStart&&(!S.brushEnd||S.brushStart>S.brushEnd)){S.brushStart='';S.brushEnd='';}if(S.range==='custom'&&!S.start)S.range='28';}
function url(next={}){const p=new URLSearchParams({...S,...next});return 'index.html?'+p;}
function change(next,replace=false){S={...S,...next};history[replace?'replaceState':'pushState']({},'',url());render();}
const appId=()=>S.app==='all'?'pois':S.app,appName=()=>S.app==='all'?'Portfolio':F.apps.find(a=>a.id===S.app).name;
const windowAll=()=>S.range==='custom'?{start:S.start,end:S.end}:A.windowFor(S.end,+S.range);
const windowNow=()=>{const w=S.brushStart?{start:S.brushStart,end:S.brushEnd}:windowAll();return S.scenario==='delay'&&w.start<='2026-10-08'&&w.end>'2026-10-08'?{...w,end:'2026-10-08'}:w;};
const comparator=()=>A.periodPair(windowNow(),S.compare,{start:S.compareStart||'2026-08-17',end:S.compareEnd||'2026-09-13'});
const selected=()=>S.selected?S.selected.split(','):[];
function stored(key,fallback){try{return JSON.parse(localStorage.getItem('kopa-ux-'+key))??fallback;}catch{return fallback;}}
function save(key,value){try{localStorage.setItem('kopa-ux-'+key,JSON.stringify(value));}catch{toast('Browser storage unavailable; URL still preserves this view.');}}
const pins=()=>stored('pins',[]),localEvents=()=>stored('experiments',[]);
function keywords(){const rows=F.keywords(appId(),S.market,S.device);if(S.scenario==='stale')return rows.map(r=>({...r,points:r.points.map(p=>p.date>'2026-10-06'?{...p,rank:null,status:'stale'}:p)}));if(S.scenario==='legacy')return rows.map(r=>({...r,points:r.points.map(p=>({...p,method:p.date<'2026-09-28'?'itunes_search_position':p.method}))}));if(S.scenario==='missing')return rows.map((r,i)=>({...r,points:r.points.map(p=>p.date>='2026-10-04'&&p.date<='2026-10-06'?{...p,rank:null,status:i===0?'failed':i===1?'absent':'untracked'}:p)}));return rows;}
function filteredKeywords(){const w=windowNow(),p=comparator();let rows=keywords().map(r=>({...r,summary:A.rankSummary(r.points,w),previous:p?A.rankSummary(r.points,p):null})).filter(r=>r.name.toLowerCase().includes(S.query.toLowerCase())&&(S.intent==='all'||r.intent===S.intent)&&(S.pinned!=='on'||pins().includes(r.id)));
 if(S.band!=='all'){const [lo,hi]=S.band.split('-').map(Number);rows=rows.filter(r=>r.summary.last&&r.summary.last.rank>=lo&&r.summary.last.rank<=hi);}
 const fields=S.sort.split(',');rows.sort((a,b)=>{if(pins().includes(a.id)!==pins().includes(b.id))return pins().includes(a.id)?-1:1;for(const key of fields){let av=key==='name'?a.name:key==='latest'?a.points.find(p=>p.date===windowNow().end)?.rank:key==='movement'?A.movement(a.summary.mean,a.previous?.mean):key==='coverage'?a.summary.coverage:a.summary.mean,bv=key==='name'?b.name:key==='latest'?b.points.find(p=>p.date===windowNow().end)?.rank:key==='movement'?A.movement(b.summary.mean,b.previous?.mean):key==='coverage'?b.summary.coverage:b.summary.mean;let v=av==null?1:bv==null?-1:typeof av==='string'?av.localeCompare(bv):av-bv;if(v)return S.descending==='true'?-v:v;}return 0;});return rows;}
function appRows(){return (S.app==='all'?F.apps:F.apps.filter(a=>a.id===S.app)).map(a=>({...a,points:F.appDays(a.id,S.market).map(p=>S.scenario==='zero'?{...p,downloads:0,spend:0,installs:0,taps:0,proceeds:0}:p)}));}
function total(rows,w){return rows.reduce((sum,r)=>{const t=A.sums(r.points,w);for(const k of ['downloads','spend','taps','installs','impressions','proceeds'])sum[k]+=t[k];sum.cpa=sum.installs?sum.spend/sum.installs:null;return sum;},{downloads:0,spend:0,taps:0,installs:0,impressions:0,proceeds:0,cpa:null});}
function mark(color,shape=0){return `<span aria-hidden="true" style="color:${color}">${['●','◆','▲'][shape%3]}</span>`;}
function delta(a,b,rank=false,inverse=false){const d=rank?A.movement(a,b):A.percent(a,b);if(d==null)return '<span class="neutral">No baseline</span>';return `<span class="${(inverse?-d:d)>0?'positive':(inverse?-d:d)<0?'negative':'neutral'}">${d>0?'↑':d<0?'↓':'→'} ${num(Math.abs(d),rank?1:0)}${rank?' places':'%'}</span>`;}
function spark(points,color,rank=false,key='downloads'){const p=A.inWindow(points,windowNow()),values=p.filter(x=>x.status==='observed').map(x=>x[rank?'rank':key]).filter(Number.isFinite);if(!values.length)return '—';const min=Math.min(...values),max=Math.max(...values),x=i=>2+i/Math.max(1,p.length-1)*78,y=v=>rank?3+(v-min)/(max-min||1)*18:21-(v-min)/(max-min||1)*18;return `<svg class="sparkline" viewBox="0 0 82 24" aria-hidden="true">${A.segments(p,r=>r[rank?'rank':key]).map(seg=>`<path d="${seg.map((r,i)=>(i?'L':'M')+x(p.indexOf(r)).toFixed(1)+','+y(r[rank?'rank':key]).toFixed(1)).join(' ')}" fill="none" stroke="${color}" stroke-width="1.5"/>`).join('')}</svg>`;}
function option(v,label,current){return `<option value="${esc(v)}" ${v===current?'selected':''}>${esc(label)}</option>`;}
function context(){const w=windowNow(),p=comparator();return `<div class="context"><select aria-label="App or portfolio" data-change="app">${option('all','All apps · portfolio',S.app)}${F.apps.map(a=>option(a.id,a.name,S.app)).join('')}</select><select aria-label="Market" data-change="market">${option('DE','Germany · DE',S.market)}${option('US','United States · US',S.market)}</select><select aria-label="Requested locale and device" data-change="device" ${S.screen!=='keywords'?'disabled title="Device segmentation unavailable for this report; retained for Keywords"':''}>${option('iphone',(S.market==='DE'?'de-DE':'en-US')+' · iPhone',S.device)}${option('ipad',(S.market==='DE'?'de-DE':'en-US')+' · iPad',S.device)}</select><div class="periods">${[7,28,90].map(n=>`<button data-range="${n}" class="${S.range==n?'active':''}" aria-pressed="${S.range==n}">${n}D</button>`).join('')}</div><button class="date-button" data-modal="dates" aria-label="Choose custom dates">${span(windowAll())} ▾</button><select aria-label="Comparison period" data-change="compare">${option('previous','Compare · previous period',S.compare)}${option('off','Comparison off',S.compare)}${option('custom','Compare · custom period',S.compare)}</select></div><div class="context-footer"><span>${span(w)} 2026${p?' vs '+span(p)+' 2026':' · no comparator'}${S.brushStart?' · selected chart range':''}${p&&A.dates(p.start,p.end).length!==A.dates(w.start,w.end).length?' · unequal windows; overlay by elapsed day':''}</span><span class="quality-inline"><i class="dot"></i> Sample snapshot · last complete ${short(S.scenario==='delay'?'2026-10-08':F.END)} · ${S.screen==='ads'?'account time Europe/Berlin':'UTC observation dates'} <button class="text-btn" data-nav="sources">Sources ↗</button></span></div>${S.app==='all'&&S.screen==='keywords'?'<div class="state-banner">Keyword observations are app-specific. Showing POIS within the portfolio context; choose an app to switch watchlists.</div>':''}`;}
function stateBanner(){const states={stale:'Stale history · last actual rank observation is 6 Oct. Later dates remain gaps; positions are not carried forward.',zero:'Legitimate zero · official sample report rows explicitly contain zero. This is separate from missing or unavailable data.',missing:'Partial collection · 4–6 Oct contains failed, absent and untracked observations. Gaps remain visible; no zeros are inferred.',legacy:'Historical method change · Legacy iTunes Search positions are dashed and excluded from vendor rank comparisons.',delay:'Reporting delay · 9–11 Oct is provisional. Mature totals stop at 8 Oct in this review state.',ambiguous:'Attribution unresolved · Spend remains available. Attributed downloads and CPA are unavailable until the attribution definition is reconciled.'};return states[S.scenario]?`<div class="state-banner" role="status">${states[S.scenario]}</div>`:'';}
function blocking(){if(S.scenario==='delay'&&windowAll().start>'2026-10-08')return '<section class="panel empty-state"><h2>No mature days in this window</h2><p>All selected dates are provisional. Choose an earlier reporting window to inspect completed reports.</p><button data-modal="dates" class="primary">Choose earlier dates</button></section>';const map={empty:['No observations yet','Your watchlist has no collected history. Choose a source and a small set of keywords to begin tracking. Historical coverage will be shown only where supplied.','Choose a sample source'],denied:['Access required','This source is unavailable to your role. The requested app, market and period stay selected. Ask a workspace administrator for read access.','View source permissions'],failed:['Collection failed','The latest collection did not complete. No measurement is substituted. Inspect the failure and retain the last successful observation date.','Inspect collection'],loading:['Loading observations','Retrieving the selected scope. Chart geometry remains reserved so the page does not jump.','Show loaded sample']};if(!map[S.scenario])return '';const [h,p,b]=map[S.scenario];return `<section class="panel empty-state" aria-live="polite"><div class="state-icon">${S.scenario==='failed'?'!':'⌁'}</div><h2>${h}</h2><p>${p}</p>${S.scenario==='loading'?'<div class="skeleton" style="width:85%;height:85px"></div>':''}<button class="primary" data-action="${S.scenario==='loading'?'normal':'source'}">${b}</button></section>`;}
function brushBanner(){return S.brushStart?`<div class="brush-banner">Analyzing ${span(windowNow())} · tables and comparisons use this range<button data-action="clearbrush">Clear selected range ×</button></div>`:'';}
function metrics(rows){const w=matureWindow(windowNow()),p=comparator(),t=total(rows,w),b=p?total(rows,p):{};const metric=[['First-time downloads',num(t.downloads),delta(t.downloads,b.downloads),'downloads','App Store Connect · report count'],['Ad spend',money(t.spend),delta(t.spend,b.spend),'spend','Native billing currency · EUR'],['Tap CPA',S.scenario==='ambiguous'?'Unavailable':money(t.cpa),S.scenario==='ambiguous'?'Definition unresolved':delta(t.cpa,b.cpa,false,true),'spend','Spend ÷ tap-attributed downloads'],['Proceeds',money(t.proceeds),delta(t.proceeds,b.proceeds),'proceeds','Developer proceeds · EUR']];return `<div class="metrics">${metric.map(([label,v,d,k,def])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${v}</div><div class="metric-spark">${spark(rows[0].points,'#82988b',false,k)}</div><div class="metric-note">${d}<span>${comparator()?'vs comparator':'comparison off'}</span></div><div class="footnote">${def}</div></div>`).join('')}</div>`;}
function matureWindow(w){return S.scenario==='delay'?{start:w.start,end:w.end>'2026-10-08'?'2026-10-08':w.end}:w;}
function chartMarkup(kind,rows,key,title,subtitle){const p=comparator();const metricTabs=kind==='rank'?['Rank history']:kind==='ads'?['spend','taps','installs','cpa','impressions']:['downloads','spend','proceeds'];const label=k=>({downloads:'First-time downloads',spend:'Spend · EUR',proceeds:'Proceeds · EUR',installs:(({tap:'Tap',view:'View',total:'Total'})[S.attribution])+' downloads',cpa:(({tap:'Tap',view:'View',total:'Total'})[S.attribution])+' CPA · EUR',impressions:'Impressions',taps:'Taps'}[k]||k);return `<section class="panel chart-panel"><div class="panel-head"><div><h2>${title}</h2><p>${subtitle}</p></div><div class="chart-actions">${kind==='rank'?'<label><input type="checkbox" id="competitor" '+(S.competitor==='on'?'checked':'')+'>Competitor</label>':''}<button data-action="explain">Explain this change ↗</button><button data-action="experiment" aria-label="Start experiment from chart">+ Note</button></div></div><div class="chart-tabs">${metricTabs.map(k=>`<button data-metric="${k}" class="${kind==='rank'||key===k?'active':''}" aria-pressed="${kind==='rank'||key===k}">${label(k)}</button>`).join('')}<span class="legend-note">${kind==='rank'?'#1 is best · daily observations':kind==='ads'?'Single metric · one unit':'Daily report values'}</span></div><div class="legend">${rows.map(r=>`<button data-series="${r.id}" class="${(S.hidden||'').split(',').includes(r.id)?'off':''}" aria-label="Toggle ${esc(r.name)}" aria-pressed="${!(S.hidden||'').split(',').includes(r.id)}">${mark(r.color,r.shape)} ${esc(r.name)}</button>`).join('')}${kind==='rank'&&S.competitor==='on'?'<span class="footnote">▲ Posture Lab · competitor fixture</span>':''}${p?'<span class="legend-note"><span class="series-mark dashed" style="--series:#788b83"></span> Previous period</span>':''}</div>${rows.length?'':'<p class="footnote">Select up to four keywords in the table to plot their histories.</p>'}<div class="plot-wrap"><svg class="main-chart" tabindex="0" role="img" aria-label="${esc(title)}. ${kind==='rank'?'Rank one at top. Gaps are unobserved.':''} Arrow keys scrub; drag selects a range." data-kind="${kind}"></svg><div class="event-controls"></div><div class="chart-tip" role="status" aria-live="polite" aria-atomic="true" hidden></div></div><div class="chart-bottom"><span>Drag to select dates · <button class="text-btn" data-modal="range">Select range</button> · ← → to scrub</span><label class="scrub-group">Scrub date <input aria-label="Scrub chart date" class="scrubber" type="range" min="0" max="${A.dates(windowAll().start,windowAll().end).length-1}" value="0"></label></div><div class="footnote">${kind==='rank'?'● Observed vendor rank · × Collection failed · ▽ Absent in top 100 · legacy = dashed · no interpolation':kind==='ads'?'Apple Ads report fixture · EUR · Europe/Berlin · attribution revisions may change totals':'App Store Connect / Apple Ads fixtures · sources remain separate · correlation does not establish cause'}</div></section>`;}
function rankCompare(){const r=keywords().find(r=>selected().includes(r.id));if(!r)return '';const c=A.rankSummary(r.points,windowNow()),p=comparator(),b=p?A.rankSummary(r.points,p):null;return `<div class="compare-summary"><div><label>${esc(r.name)} · mean observed rank</label><strong>${num(c.mean,1)} ${b?'← '+num(b.mean,1):''}</strong><small>${b?delta(c.mean,b.mean,true):'Comparison off'}</small></div><div><label>Observed boundary positions</label><strong>${c.first?'#'+c.first.rank+' → #'+c.last.rank:'—'}</strong><small>${c.first?short(c.first.date)+' → '+short(c.last.date):'No comparable vendor observations'}</small></div><div><label>Volatility · standard deviation</label><strong>${num(c.volatility,1)} positions</strong><small>Observed days only; descriptive</small></div><div><label>Successful collection coverage</label><strong>${c.collected} / ${c.expected} days</strong><small>${c.observed} observed${b?' · prior '+b.collected+'/'+b.expected:' · absent counts as collected'}</small></div></div>`;}
function keywordTable(){const rows=filteredKeywords();let group='';return `<div class="table-area"><div class="section-title"><div><h2>Tracked keyword watchlist <span class="pill">${rows.length}</span></h2><p>Select rows to compare. Open a keyword for the evidence.</p></div><button class="text-btn" data-action="resetselection">Reset selection</button></div><section class="panel table-panel"><div class="table-toolbar"><input aria-label="Search keywords" placeholder="Search keywords…" value="${esc(S.query)}" id="keyword-search"><select aria-label="Filter keyword intent" data-change="intent">${['all','Core intent','Feature','Discovery','Brand'].map(v=>option(v,v==='all'?'All intents':v,S.intent)).join('')}</select><select aria-label="Filter rank band" data-change="band">${['all','1-1','2-5','6-10','11-20','21-50','51-100'].map(v=>option(v,v==='all'?'All rank bands':'#'+v,S.band)).join('')}</select><select class="group-control" aria-label="Group by intent" data-change="group">${option('off','No grouping',S.group)}${option('on','Group by intent',S.group)}</select><button data-action="pinned" aria-pressed="${S.pinned==='on'}">${S.pinned==='on'?'★ Pinned only':'☆ Pinned'}</button><span class="count">${selected().length} plotted · max 4</span><button data-action="export">Export CSV ↓</button></div><div class="table-scroll"><table aria-label="Tracked keyword observations"><thead><tr><th><input type="checkbox" aria-label="Plot first four visible keywords" id="bulk"></th><th><button data-sort="name">Keyword ${S.sort.includes('name')?'↕':''}</button></th><th class="num"><button data-sort="latest">Latest</button></th><th class="num"><button data-sort="movement">Mean Δ</button></th><th>History</th><th class="secondary-col">Intent</th><th class="num secondary-col"><button data-sort="coverage">Coverage</button></th><th class="secondary-col">Method</th><th>Pin</th></tr></thead><tbody>${(S.group==='on'?[...rows].sort((a,b)=>a.intent.localeCompare(b.intent)):rows).map(r=>{const head=S.group==='on'&&group!==r.intent?`<tr class="table-group"><td colspan="9">${esc(r.intent)}</td></tr>`:'';group=r.intent;const end=r.points.find(p=>p.date===windowNow().end),latest=end?.status==='observed'?'#'+end.rank:end?.status==='absent'?'>100':end?.status==='failed'?'Failed':end?.status==='stale'?'Stale · 6 Oct':'Untracked';return head+`<tr data-row="${r.id}" class="${selected().includes(r.id)?'row-selected':''}"><td><input type="checkbox" aria-label="Plot ${esc(r.name)}" data-select="${r.id}" ${selected().includes(r.id)?'checked':''}></td><td><button class="keyword-button" data-keyword="${r.id}">${mark(r.color,r.shape)}${esc(r.name)}</button></td><td class="num rank-cell">${latest}</td><td class="num">${delta(r.summary.mean,r.previous?.mean,true)}</td><td>${spark(r.points,r.color,true)}</td><td class="secondary-col"><span class="pill">${esc(r.intent)}</span></td><td class="num secondary-col coverage">${r.summary.collected}/${r.summary.expected}</td><td class="secondary-col muted">${end?.method==='itunes_search_position'?'Legacy iTunes':'Vendor observation'}</td><td><button class="favorite ${pins().includes(r.id)?'is-on':''}" aria-label="Pin ${esc(r.name)}" data-pin="${r.id}" aria-pressed="${pins().includes(r.id)}">${pins().includes(r.id)?'★':'☆'}</button></td></tr>`;}).join('')}${rows.length?'':'<tr><td colspan="9">No keywords match these filters. <button class="text-btn" data-action="clearfilters">Clear table filters</button></td></tr>'}</tbody></table></div><div class="research-footer"><span>Mean Δ = previous observed mean − current observed mean · positive means improvement</span><span>Shift + click a header adds a secondary sort · only tracked terms</span></div></section><div class="split-caption">SIGNAL · Keep the watchlist and chart in one horizontal workspace.</div></div>`;}
function keywordScreen(){const rows=keywords().filter(r=>selected().includes(r.id));return brushBanner()+rankCompare()+`<div class="analysis-workbench">${chartMarkup('rank',rows,'rank','How are your keywords moving?','Comparable storefront and device · select a line to investigate')}${keywordTable()}</div>`;}
function overviewTable(){const w=matureWindow(windowNow()),p=comparator();return `<div class="table-area"><div class="section-title"><h2>Apps in this view</h2><p>Open an app to investigate its keywords</p></div><section class="panel table-panel"><div class="table-scroll"><table aria-label="App performance"><thead><tr><th>App</th><th>Download trend</th><th class="num">First-time downloads</th><th class="num">Change</th><th class="num">Ad spend · EUR</th><th>Source status</th></tr></thead><tbody>${appRows().map(r=>{const t=A.sums(r.points,w),b=p?A.sums(r.points,p):{};return `<tr><td><button class="app-button" data-app="${r.id}"><span class="app-icon" style="--app-color:${r.color}">${r.letter}</span><span>${r.name}<small class="muted">${S.market} · ${r.description}</small></span></button></td><td>${spark(r.points,r.color)}</td><td class="num">${num(t.downloads)}</td><td class="num">${delta(t.downloads,b.downloads)}</td><td class="num">${money(t.spend)}</td><td><span class="pill">✓ Complete to ${short(w.end)}</span></td></tr>`;}).join('')}</tbody></table></div></section></div>`;}
function investigations(){const r=filteredKeywords().find(r=>r.summary.mean!=null);return `<div class="section-title"><h2>Three places to look next</h2><p>Deterministic examples from this fixture · no AI inference</p></div><div class="investigations"><article class="investigation"><span class="index">01 · KEYWORD MOVEMENT</span><h3>Inspect the shape behind the change</h3><p>${esc(r?.name||'Posture keywords')} has comparable observations in the selected window. Check the daily history and coverage before acting.</p><button class="text-btn" data-nav="keywords">Inspect keywords ↗</button></article><article class="investigation"><span class="index">02 · ACQUISITION</span><h3>Where did the spend move?</h3><p>Compare the current period with the prior complete window. Separate spend changes from attributed outcomes.</p><button class="text-btn" data-nav="ads">Review campaigns ↗</button></article><article class="investigation"><span class="index">03 · CONTEXT</span><h3>Put changes on the timeline</h3><p>Metadata and experiment annotations provide context. Their timing alone cannot explain an outcome.</p><button class="text-btn" data-nav="experiments">Open timeline ↗</button></article></div>`;}
function overviewScreen(){const rows=appRows(),key=['downloads','spend','proceeds'].includes(S.metric)?S.metric:'downloads';return brushBanner()+metrics(rows)+`<div class="analysis-workbench">${chartMarkup('overview',rows,key,'What changed across your apps?','Daily '+({downloads:'first-time downloads',spend:'ad spend in EUR',proceeds:'developer proceeds in EUR'}[key])+' · click an app to continue')}${overviewTable()}</div>`+investigations();}
function adsRows(){let rows=F.campaigns(appId(),S.market,S.level,S.parent);const parentFactor=S.parent.split('/').filter(Boolean).reduce((n,id)=>n*(id.startsWith('campaign')?[.22,.47,.31][+id.split('-')[1]]:id.startsWith('group')?[.65,.35][+id.split('-')[1]]:1),1);return rows.map(r=>({...r,points:r.points.map(p=>({...p,...(S.scenario==='zero'?{spend:0,taps:0,installs:0,impressions:0}:{}),spend:+(p.spend*parentFactor).toFixed(2),taps:Math.round(p.taps*parentFactor),impressions:Math.round(p.impressions*parentFactor),installs:Math.round(p.installs*parentFactor*(S.attribution==='total'?1.15:S.attribution==='view'?.15:1)),method:'official_report',...(S.scenario==='zero'?{spend:0,taps:0,installs:0,impressions:0}:{} )}))})).filter(r=>r.name.toLowerCase().includes(S.query.toLowerCase())).sort((a,b)=>{const w=matureWindow(windowNow()),d=A.sums(a.points,w).spend-A.sums(b.points,w).spend;return S.adsSort==='asc'?d:-d;});}
function adsMetrics(rows){const w=matureWindow(windowNow()),p=comparator(),t=total(rows,w),b=p?total(rows,p):{},ambiguous=S.scenario==='ambiguous',type=({tap:'Tap',view:'View',total:'Total'})[S.attribution];const items=[['Ad spend',money(t.spend),delta(t.spend,b.spend),'spend','Native billing EUR'],['Taps',num(t.taps),delta(t.taps,b.taps),'taps','Reported taps · selected drilldown'],[type+'-attributed downloads',ambiguous?'Unavailable':num(t.installs),ambiguous?'Definition unresolved':delta(t.installs,b.installs),'installs',type+' attribution · report fixture'],[type+' CPA',ambiguous?'Unavailable':money(t.cpa),ambiguous?'Definition unresolved':delta(t.cpa,b.cpa,false,true),'spend','Sum spend ÷ attributed downloads']];return `<div class="metrics">${items.map(([l,v,d,k,n])=>`<div class="metric"><div class="metric-label">${l}</div><div class="metric-value">${v}</div><div class="metric-spark">${rows.length?spark(rows[0].points,'#82988b',false,k):''}</div><div class="metric-note">${d}</div><div class="footnote">${n}</div></div>`).join('')}</div>`;}
function adsScreen(){const rows=adsRows(),w=matureWindow(windowNow()),p=comparator(),key=['spend','taps','installs','cpa','impressions'].includes(S.metric)?S.metric:'spend';return brushBanner()+`<div class="trail"><button data-level="campaign">Campaigns</button>${S.parent?'<span>/</span><button data-level="group">Selected campaign</button>':''}${S.level==='keyword'||S.level==='term'?'<span>/</span><span>Selected ad group</span>':''}<span style="margin-left:auto">${S.market} storefront · billed EUR</span><select aria-label="Attribution type" data-change="attribution">${option('tap','Tap-attributed downloads',S.attribution)}${option('view','View-attributed downloads',S.attribution)}${option('total','Total attributed downloads',S.attribution)}</select></div>${adsMetrics(rows)}<div class="analysis-workbench">${chartMarkup('ads',S.scenario==='ambiguous'&&['installs','cpa'].includes(key)?[]:rows,key,'Follow the spend. Check the outcome.','Apple Ads · '+(({tap:'tap-attributed',view:'view-attributed',total:'total attributed'})[S.attribution])+' downloads · mature reporting days only')}<div class="table-area"><div class="section-title"><h2>${({campaign:'Campaigns',group:'Ad groups',keyword:'Targeting keywords',term:'Reported search terms'})[S.level]||'Campaigns'}</h2><div class="actions">${['keyword','term'].includes(S.level)?`<button data-level="keyword">Targeting keywords</button><button data-level="term">Reported terms</button>`:''}</div></div><section class="panel table-panel"><div class="table-toolbar"><input id="ads-search" aria-label="Search Apple Ads rows" placeholder="Search ${S.level}s…" value="${esc(S.query)}"><span class="count">${rows.length} rows · read only</span><button data-action="export">Export CSV ↓</button></div><div class="table-scroll"><table aria-label="Apple Ads performance"><thead><tr><th>${S.level==='term'?'Reported query':S.level==='keyword'?'Targeting keyword':'Name'}</th><th>Daily spend</th><th class="num"><button data-ads-sort="spend">Spend · EUR ↕</button></th><th class="num">Δ spend</th><th class="num">Taps</th><th class="num">${({tap:'Tap',view:'View',total:'Total'})[S.attribution]} downloads</th><th class="num">${({tap:'Tap',view:'View',total:'Total'})[S.attribution]} CPA</th><th>Evidence</th></tr></thead><tbody>${rows.sort((a,b)=>S.adsSort==='asc'?A.sums(a.points,w).spend-A.sums(b.points,w).spend:A.sums(b.points,w).spend-A.sums(a.points,w).spend).map(r=>{const t=A.sums(r.points,w),b=p?A.sums(r.points,p):{};return `<tr><td><button class="keyword-button" data-drill="${r.id}">${mark(r.color,r.shape)}${esc(r.name)} ${['campaign','group'].includes(S.level)?'›':''}</button>${['keyword','term'].includes(S.level)?'<br><small>'+r.match+'</small>':''}</td><td>${spark(r.points,r.color,false,'spend')}</td><td class="num">${money(t.spend)}</td><td class="num">${delta(t.spend,b.spend)}</td><td class="num">${num(t.taps)}</td><td class="num">${S.scenario==='ambiguous'?'Unavailable':num(t.installs)}</td><td class="num">${S.scenario==='ambiguous'?'Unavailable':money(t.cpa)}</td><td><span class="pill">${S.scenario==='delay'?'Provisional tail excluded':'Report fixture'}</span></td></tr>`;}).join('')}</tbody></table></div><div class="research-footer"><span>${S.level==='term'?'Reported terms may be suppressed; displayed rows are not all queries.':'Targeting keywords describe bidding intent; reported terms describe actual queries.'}</span><span>Attribution definition and reporting currency travel with the export</span></div></section></div></div>`;}
function sourceScreen(){return `<section class="panel table-panel"><div class="panel-head" style="padding:20px"><div><h2>Can this view be trusted?</h2><p>Coverage for ${appName()} · ${S.market} · sample connection matrix</p></div><span class="pill">Read-only design review</span></div><div class="table-scroll"><table aria-label="Source reliability matrix"><thead><tr><th>Source / scope</th><th>State</th><th>Last complete date</th><th>Expected delay</th><th>Issue / next action</th></tr></thead><tbody>${[['App Store Connect','✓ Complete','11 Oct','2–3 days','Daily first-time downloads; report instances reconciled'],['Apple Ads','◷ Provisional','8 Oct','Attribution revisions','Review late revisions; keep native EUR and account timezone'],['Rank observation provider','△ Partial','11 Oct','Daily','Two failed POIS observations; inspect collection'],['Legacy iTunes Search','Historical only','18 Aug','Discontinued series','Keep separate from validated rank observations'],['Product events','○ Not connected','—','Unknown','Read access required; no events inferred']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><div class="section-title"><h2>Observation vocabulary</h2></div><div class="investigations"><article class="investigation"><h3>Observed #24</h3><p>A rank was measured for this app, storefront, device, method and date.</p><h3>Absent within top 100</h3><p>Collection succeeded; no position appeared within the measured depth. This is not #101.</p></article><article class="investigation"><h3>Failed / not yet tracked</h3><p>No measurement exists. Preserve a gap and exclude it from averages.</p><h3>Stale</h3><p>Show the last actual date; never carry its position forward as a new observation.</p></article><article class="investigation"><h3>Official / vendor model / legacy</h3><p>Report count, estimated model and legacy search position are separate methods. No cross-method rank change is calculated.</p><button data-action="diagnostics">Inspect sample diagnostics ↗</button></article></div>`;}
function experimentsScreen(){const list=[...F.events.map(e=>({...e,status:e.type==='Observational'?'Awaiting data':'Reviewed'})),...localEvents()].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="state-banner">Local sample journal · notes are stored only in this browser. Observational notes and controlled Apple PPO experiments require separate evaluation designs.</div><section class="panel"><div class="timeline">${list.map(e=>`<article><div class="eyebrow">${short(e.date)} · ${esc(e.status||'Planned')} · ${esc(e.type||'Observational')}</div><h2>${esc(e.name)}</h2><p>${esc(e.detail||e.hypothesis)}</p>${e.criteria?'<p>Success criterion: '+esc(e.criteria)+'</p>':''}<button class="text-btn" data-event="${esc(e.date)}">Inspect annotation ↗</button></article>`).join('')}</div></section>`;}
function render(){resizeObserver?.disconnect();document.body.dataset.direction=S.direction;document.title=names[S.screen]+' · Kopa UX review';const title={overview:['Portfolio intelligence','Notice the movement. Follow it to the evidence.'],keywords:['Keyword intelligence','See the history. Compare the shape. Understand the context.'],ads:['Apple Ads','Investigate acquisition with a clear attribution context.'],experiments:['Experiments & changes','A connected record of hypotheses, interventions and evidence.'],sources:['Sources & coverage','Know what is complete before you decide.']}[S.screen];$('#app').innerHTML=`<div class="reviewbar"><div class="sample-label"><i class="sample-dot"></i><strong>Sample-data prototype</strong><span class="sample-detail">Sample data only · no live connections</span></div><div class="directions"><button data-direction="fieldwork" class="${S.direction==='fieldwork'?'active':''}">A · Fieldwork</button><button data-direction="signal" class="${S.direction==='signal'?'active':''}">B · Signal</button><select class="state-select" aria-label="Review data state" data-change="scenario">${[['normal','Normal sample'],['missing','Missing observations'],['legacy','Method discontinuity'],['stale','Stale rank history'],['empty','Empty account'],['delay','Reporting delay'],['ambiguous','Ambiguous paid data'],['failed','Collection failed'],['denied','No permission'],['loading','Loading'],['zero','Legitimate zero']].map(([v,l])=>option(v,l,S.scenario)).join('')}</select><a href="../review.html">Review guide ↗</a></div></div><div class="shell"><aside class="sidebar"><a class="wordmark" href="index.html?screen=overview&app=all" aria-label="Kopa Overview">K<span class="full-word">OPA</span><span>STUDIO / INTELLIGENCE</span></a><nav class="nav" aria-label="Main navigation">${Object.entries(names).map(([k,v])=>`<a href="${esc(url({screen:k,query:'',drawer:''}))}" data-nav="${k}" class="${S.screen===k?'active':''}" ${S.screen===k?'aria-current="page"':''} title="${v}"><span class="navicon" aria-hidden="true">${icons[k]}</span><span class="nav-label">${v}</span></a>`).join('')}</nav><div class="side-meta"><span class="avatar">K</span> Kopa workspace<div class="side-divider"></div>October 2026 snapshot<br>Independent sample dataset<br>Local notes & saved views</div></aside><div class="workspace"><header class="topline"><div class="crumb">Workspace <span>/</span> <strong>${names[S.screen]}</strong></div><button class="global-search" data-modal="command"><span class="search-text">Jump to an app or view</span><span class="kbd">⌘ K</span></button></header><main id="content" tabindex="-1"><div class="title-row"><div><div class="eyebrow">${appName()} · ${S.market==='DE'?'Germany':'United States'}</div><h1>${title[0]}</h1><p class="subtitle">${title[1]}</p></div><div class="actions"><button data-modal="saved">Saved views ▾</button><button data-modal="save" class="primary">Save view</button></div></div>${context()}${stateBanner()}${blocking()||({keywords:keywordScreen,overview:overviewScreen,ads:adsScreen,experiments:experimentsScreen,sources:sourceScreen}[S.screen])()}<div class="review-hint">${S.direction==='fieldwork'?'FIELDWORK · Recommended direction':'SIGNAL · Alternate direction'} · Every number is synthetic · This prototype makes no network requests and cannot change ads, metadata or production data.</div></main></div></div>`;bind();paintChart();if(S.drawer)openDrawer(S.drawer,false);else $('#overlay').innerHTML='';}
function toggleSeries(id){const a=selected(),next=a.includes(id)?a.filter(x=>x!==id):[...a,id];if(next.length>4)return toast('Compare up to four keywords at a time. Unselect one to add another.');change({selected:next.join(',')});}
function bind(){document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=ev=>{ev.preventDefault();change({screen:e.dataset.nav,drawer:'',query:'',metric:e.dataset.nav==='ads'?'spend':'downloads'});});document.querySelectorAll('[data-direction]').forEach(e=>e.onclick=()=>change({direction:e.dataset.direction}));document.querySelectorAll('[data-range]').forEach(e=>e.onclick=()=>change({range:e.dataset.range,start:'',brushStart:'',brushEnd:''}));document.querySelectorAll('[data-change]').forEach(e=>e.onchange=()=>{const k=e.dataset.change;if(k==='compare'&&e.value==='custom'){modal('dates');return;}change({[k]:e.value,drawer:'',...(k==='app'||k==='market'||k==='device'?{parent:'',level:'campaign',brushStart:'',brushEnd:''}:{})});});document.querySelectorAll('[data-select]').forEach(e=>e.onclick=()=>toggleSeries(e.dataset.select));document.querySelectorAll('[data-series]').forEach(e=>e.onclick=()=>{if(S.screen==='keywords')toggleSeries(e.dataset.series);else {const a=(S.hidden||'').split(',').filter(Boolean),id=e.dataset.series;change({hidden:(a.includes(id)?a.filter(x=>x!==id):[...a,id]).join(',')});}});document.querySelectorAll('[data-keyword]').forEach(e=>e.onclick=()=>openDrawer('keyword:'+e.dataset.keyword));document.querySelectorAll('[data-pin]').forEach(e=>e.onclick=()=>{const p=pins();save('pins',p.includes(e.dataset.pin)?p.filter(x=>x!==e.dataset.pin):[...p,e.dataset.pin]);render();});document.querySelectorAll('[data-sort]').forEach(e=>e.onclick=ev=>{const k=e.dataset.sort;change({sort:ev.shiftKey?[...new Set([...S.sort.split(','),k])].join(','):k,descending:S.sort===k&&S.descending!=='true'?'true':'false'});});document.querySelectorAll('[data-app]').forEach(e=>e.onclick=()=>change({app:e.dataset.app,screen:'keywords',drawer:'',query:''}));document.querySelectorAll('[data-metric]').forEach(e=>e.onclick=()=>e.dataset.metric==='Rank history'?null:change({metric:e.dataset.metric}));document.querySelectorAll('[data-event]').forEach(e=>e.onclick=()=>openDrawer('event:'+e.dataset.event));document.querySelectorAll('[data-drill]').forEach(e=>e.onclick=()=>{if(['keyword','term'].includes(S.level)){openDrawer('paid:'+e.dataset.drill);return;}change({level:S.level==='campaign'?'group':'keyword',parent:[S.parent,e.dataset.drill].filter(Boolean).join('/'),query:''});});document.querySelectorAll('[data-level]').forEach(e=>e.onclick=()=>change({level:e.dataset.level,parent:e.dataset.level==='campaign'?'':e.dataset.level==='group'?S.parent.split('/')[0]:S.parent,query:''}));document.querySelectorAll('[data-ads-sort]').forEach(e=>e.onclick=()=>change({adsSort:S.adsSort==='asc'?'desc':'asc'}));['keyword-search','ads-search'].forEach(id=>{const e=$('#'+id);if(e)e.oninput=()=>{const pos=e.selectionStart;S.query=e.value;history.replaceState({},'',url());render();const n=$('#'+id);n.focus();n.setSelectionRange(pos,pos);};});if($('#bulk'))$('#bulk').onclick=e=>change({selected:selected().length<4?filteredKeywords().slice(0,4).map(r=>r.id).join(','):''});if($('#competitor'))$('#competitor').onclick=e=>change({competitor:S.competitor==='on'?'off':'on'});document.querySelectorAll('[data-row]').forEach(e=>{e.onmouseenter=()=>highlight(e.dataset.row);e.onmouseleave=()=>highlight(null);});}
function action(a){if(a==='source')change({screen:'sources',scenario:'normal'});if(a==='normal')change({scenario:'normal'});if(a==='clearbrush')change({brushStart:'',brushEnd:''});if(a==='clearfilters')change({query:'',intent:'all',band:'all',pinned:'off'});if(a==='pinned')change({pinned:S.pinned==='on'?'off':'on'});if(a==='resetselection')change({selected:'k0,k1'});if(a==='explain')openDrawer('explain');if(a==='experiment')modal('experiment');if(a==='export')exportCSV();if(a==='diagnostics')openDrawer('diagnostics');}
function highlight(id){document.querySelectorAll('[data-row]').forEach(r=>r.classList.toggle('row-highlight',r.dataset.row===id));document.querySelectorAll('.data-line').forEach(p=>p.style.opacity=!id||p.dataset.line===id?'1':'.25');}
function paintChart(){const svg=$('.main-chart');if(!svg)return;const kind=svg.dataset.kind,w=windowAll(),days=A.dates(w.start,w.end),p=comparator(),pd=p?A.dates(p.start,p.end):[];let rows=kind==='rank'?keywords().filter(r=>selected().includes(r.id)):kind==='ads'?adsRows():appRows();if(kind==='rank'&&S.competitor==='on'){const base=keywords()[0];rows=[...rows,{...base,id:'competitor',name:'Posture Lab · competitor fixture',color:'#71817b',shape:2,points:base.points.map((x,i)=>({...x,rank:x.rank==null?null:Math.min(100,x.rank+6+Math.round(Math.sin(i/6)*2))}))}];}rows=rows.filter(r=>!(S.hidden||'').split(',').includes(r.id));const key=kind==='rank'?'rank':kind==='ads'?(['spend','taps','installs','cpa','impressions'].includes(S.metric)?S.metric:'spend'):['downloads','spend','proceeds'].includes(S.metric)?S.metric:'downloads';if(kind==='ads'&&S.scenario==='ambiguous'&&['installs','cpa'].includes(key))rows=[];
 const draw=()=>{const W=Math.max(240,svg.clientWidth),H=svg.clientHeight,L=39,R=W-12,T=30,B=H-34,inner=R-L,x=i=>L+i/Math.max(1,days.length-1)*inner;const value=r=>key==='cpa'?(r.installs?r.spend/r.installs:null):r[key];const valid=r=>!(S.scenario==='delay'&&kind!=='rank'&&r.date>'2026-10-08');const allVals=rows.flatMap(r=>[...A.inWindow(r.points,w),...(p?A.inWindow(r.points,p):[])].filter(valid).map(value)).filter(Number.isFinite);const max=kind==='rank'?Math.max(50,Math.ceil(Math.max(1,...allVals)/10)*10):Math.max(1,...allVals)*1.12;const y=v=>kind==='rank'?A.rankY(v,max,H,T):B-v/max*(B-T);let out='';const ticks=kind==='rank'?[1,10,20,30,40,50,70,100].filter(n=>n<=max):[0,.25,.5,.75,1].map(n=>n*max);for(const n of ticks)out+=`<line x1="${L}" x2="${R}" y1="${y(n)}" y2="${y(n)}" class="gridline"/><text x="${L-9}" y="${y(n)+3}" text-anchor="end">${kind==='rank'?'#':''}${num(n,n<5&&key==='cpa'?1:0)}</text>`;for(const i of [...new Set([0,Math.round((days.length-1)*.25),Math.round((days.length-1)*.5),Math.round((days.length-1)*.75),days.length-1])])out+=`<text x="${x(i)}" y="${H-9}" text-anchor="${i===0?'start':i===days.length-1?'end':'middle'}">${short(days[i])}</text>`;
 const path=(seg,indices,cls,color,id,dash='')=>`<path d="${seg.map((v,i)=>(i?'L':'M')+x(indices(v)).toFixed(1)+','+y(value(v)).toFixed(1)).join(' ')}" class="data-line ${cls}" data-line="${id}" stroke="${color}" ${dash} />`;
 rows.forEach(r=>{const points=A.inWindow(r.points,w).map(v=>valid(v)?v:{...v,status:'provisional'});if(p){const prev=A.inWindow(r.points,p).slice(0,days.length).map(v=>kind==='rank'&&v.method!=='vendor_observation'?{...v,status:'legacy'}:v);A.segments(prev,value).forEach(seg=>{out+=path(seg,v=>pd.indexOf(v.date),'previous-line',r.color,r.id);});}A.segments(points,value).forEach(seg=>{const legacy=kind==='rank'&&seg[0].method==='itunes_search_position';out+=path(seg,v=>days.indexOf(v.date),'',r.color,r.id,legacy?'stroke-dasharray="2 5"':'');seg.filter((v,i)=>i===seg.length-1||seg.length===1).forEach(v=>{const X=x(days.indexOf(v.date)),Y=y(value(v));out+=r.shape===1?`<path d="M${X},${Y-4} L${X+4},${Y} L${X},${Y+4} L${X-4},${Y} Z" fill="white" stroke="${r.color}" stroke-width="1.6"/>`:r.shape===2?`<path d="M${X},${Y-4} L${X+4},${Y+3} L${X-4},${Y+3} Z" fill="white" stroke="${r.color}" stroke-width="1.6"/>`:`<circle cx="${X}" cy="${Y}" r="3" fill="white" stroke="${r.color}" stroke-width="1.6"/>`;});});if(kind==='rank')points.filter(v=>v.status!=='observed').forEach(v=>{out+=`<text x="${x(days.indexOf(v.date))}" y="${B-2}" text-anchor="middle" style="fill:${r.color};font-size:13px">${v.status==='failed'?'×':v.status==='absent'?'▽':'·'}</text>`;});});
 const events=[...F.events,...localEvents()].filter(e=>e.date>=w.start&&e.date<=w.end);events.forEach((e,i)=>{const X=x(days.indexOf(e.date));out+=`<g class="event-mark" aria-hidden="true"><line x1="${X}" x2="${X}" y1="${T}" y2="${B}" class="event-line"/><rect x="${X-7}" y="7" width="14" height="14" rx="3" fill="#eef2eb" stroke="#b5c1b7"/><text x="${X}" y="17" text-anchor="middle">${i+1}</text></g>`;});if(S.brushStart){const left=x(Math.max(0,days.indexOf(S.brushStart))),right=x(Math.max(0,days.indexOf(S.brushEnd)));out+=`<rect x="${left}" y="${T}" width="${right-left}" height="${B-T}" fill="#7db3a4" opacity=".12"/>`;}
 out+=`<rect id="brush-rect" x="0" y="${T}" width="0" height="${B-T}" fill="#7db3a4" opacity=".2"/><line id="crosshair" x1="0" x2="0" y1="${T}" y2="${B}" stroke="#60736b" stroke-dasharray="3 3" visibility="hidden"/>`;svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML=out;$('.event-controls').innerHTML=events.map((e,i)=>`<button data-event="${e.date}" aria-label="Inspect event ${esc(e.name)}" title="${esc(e.name)} · ${short(e.date)}" style="left:${x(days.indexOf(e.date))-8}px">${i+1}</button>`).join('');chartInfo={rows,days,pd,w,p,kind,key,W,H,L,R,T,B,x,y,value};svg.querySelectorAll('[data-event]').forEach(e=>{e.onkeydown=ev=>{if(ev.key==='Enter')openDrawer('event:'+e.dataset.event);};});};draw();resizeObserver=new ResizeObserver(draw);resizeObserver.observe(svg);
 const index=ev=>Math.max(0,Math.min(days.length-1,Math.round((ev.clientX-svg.getBoundingClientRect().left-chartInfo.L)/(chartInfo.R-chartInfo.L)*(days.length-1))));svg.onpointermove=ev=>{if(ev.target.closest('[data-event]'))return;const i=index(ev);showTip(i);highlight(ev.target.dataset?.line||null);if(brushStart!==null){const rect=$('#brush-rect');rect.setAttribute('x',chartInfo.x(Math.min(i,brushStart)));rect.setAttribute('width',Math.abs(chartInfo.x(i)-chartInfo.x(brushStart)));}};svg.onpointerleave=()=>{if(brushStart===null){hideTip();highlight(null);}};svg.onpointerdown=ev=>{if(ev.target.closest('[data-event]'))return;brushStart=index(ev);svg.setPointerCapture(ev.pointerId);};svg.onpointerup=ev=>{if(brushStart===null)return;const end=index(ev),start=brushStart;brushStart=null;if(Math.abs(end-start)>=2)change({brushStart:days[Math.min(start,end)],brushEnd:days[Math.max(start,end)]});};svg.onpointercancel=()=>{brushStart=null;};svg.onclick=ev=>{const id=ev.target.dataset?.line;if(kind==='rank'&&id&&id!=='competitor')openDrawer('keyword:'+id);};svg.onkeydown=ev=>{if(ev.key==='ArrowRight'||ev.key==='ArrowLeft'){ev.preventDefault();showTip(Math.max(0,Math.min(days.length-1,hover+(ev.key==='ArrowRight'?1:-1))));}if(ev.key==='Escape')hideTip();};$('.scrubber').oninput=ev=>showTip(+ev.target.value);
}
function hideTip(){if($('.chart-tip'))$('.chart-tip').hidden=true;if($('#crosshair'))$('#crosshair').setAttribute('visibility','hidden');}
function statusText(p){if(!p)return 'No observation';if(p.status==='failed')return 'Collection failed';if(p.status==='stale')return 'Stale · last actual 6 Oct';if(p.status==='absent')return 'Absent in top 100';if(p.status==='untracked')return 'Not yet tracked';return p.method==='itunes_search_position'?'Legacy iTunes Search position':'Vendor observation';}
function showTip(i){if(!chartInfo)return;hover=i;const c=chartInfo,date=c.days[i],pi=c.pd.length?i:-1,priorDate=c.pd[pi],tip=$('.chart-tip');$('#crosshair').setAttribute('x1',c.x(i));$('#crosshair').setAttribute('x2',c.x(i));$('#crosshair').setAttribute('visibility','visible');tip.hidden=false;tip.style.left=Math.max(0,Math.min(c.W-245,c.x(i)+12))+'px';tip.innerHTML=`<header><span>${short(date)} 2026</span><span>Sample</span></header>${c.rows.map(r=>{const p=r.points.find(v=>v.date===date),b=r.points.find(v=>v.date===priorDate),v=p&&c.value(p),pv=b&&c.value(b),provisional=S.scenario==='delay'&&c.kind!=='rank'&&date>'2026-10-08',current=provisional?'Provisional · excluded':c.kind==='rank'?p?.status==='observed'?'#'+p.rank:statusText(p):num(v,['spend','cpa','proceeds'].includes(c.key)?2:0);return `<div class="tip-row"><span>${mark(r.color,r.shape)} ${esc(r.name)}</span><strong>${current}</strong></div><small>${c.kind==='rank'?statusText(p)+' · '+esc(p?.provider||'no source'):['spend','cpa','proceeds'].includes(c.key)?'EUR · official report fixture':'Official report fixture'}${priorDate?'<br>Prior '+short(priorDate)+': '+(c.kind==='rank'?b?.status==='observed'&&b.method==='vendor_observation'?'#'+b.rank:'Not comparable':num(pv,2)):''}</small>`;}).join('')}<div class="tip-date"><small>${appName()} · ${S.market} · ${S.device} · ${c.kind==='rank'?'observation 08:00 UTC':'Europe/Berlin'}<br>Fixture values only · no causal inference</small></div>`;$('.scrubber').value=i;$('.scrubber').setAttribute('aria-valuetext',short(date)+' 2026');}
function openDrawer(id,push=true){if(push){S.drawer=id;history.pushState({},'',url());}lastFocus=document.activeElement;let content='',heading='',eyebrow='Sample evidence';const w=windowNow(),p=comparator();if(id.startsWith('keyword:')){const r=keywords().find(r=>r.id===id.split(':')[1]);if(!r)return;const c=A.rankSummary(r.points,w),b=p?A.rankSummary(r.points,p):null;heading=r.name;content=`<div class="drawer-metrics"><div><small>Mean observed rank</small><strong>${num(c.mean,1)}</strong></div><div><small>Confirmed movement</small><strong>${delta(c.mean,b?.mean,true)}</strong></div></div><h3>Daily history</h3><div style="transform:scale(2);transform-origin:left;margin:14px 0 35px">${spark(r.points,r.color,true)}</div><dl><dt>Scope</dt><dd>${appName()} · ${S.market} · ${S.device}</dd><dt>Method</dt><dd>Vendor observation fixture</dd><dt>Coverage</dt><dd>${c.collected}/${c.expected} collected days</dd><dt>Observation depth</dt><dd>Top 100</dd></dl><h3>Specific observations</h3><table class="obs-table" aria-label="Recent keyword observations"><thead><tr><th>Date</th><th>Position / status</th></tr></thead><tbody>${A.inWindow(r.points,w).slice(-8).reverse().map(p=>`<tr><td>${short(p.date)}</td><td>${p.status==='observed'?'Observed #'+p.rank:statusText(p)}</td></tr>`).join('')}</tbody></table><h3>Matched competitor context</h3><p>Use the Competitor toggle to compare a single synthetic competitor in the same storefront, device, dates and method. A real provider contract is required for production.</p><h3>Related paid evidence</h3><p>No validated keyword-to-query join in this sample. Similar wording does not prove an organic / paid relationship.</p><h3>Metadata & changes</h3>${F.events.filter(e=>e.date>=w.start&&e.date<=w.end).map(e=>`<p>${short(e.date)} · ${e.name}</p>`).join('')}<label class="footnote">Local note<textarea id="keyword-note" aria-label="Local keyword note" placeholder="Record a question or observation…">${esc(stored('note-'+r.id,''))}</textarea></label><button id="save-note">Save local note</button><button class="primary" id="drawer-experiment">Start experiment from this chart</button>`;}
else if(id.startsWith('event:')){const e=[...F.events,...localEvents()].find(e=>e.date===id.slice(6));heading=e?.name||'Chart annotation';content=`<p>${short(id.slice(6))} 2026 · ${esc(e?.type||'Observational')} · ${esc(e?.status||'Recorded')}</p><h3>What changed</h3><p>${esc(e?.detail||e?.hypothesis||'No additional detail')}</p>${e?.criteria?'<h3>Success criterion</h3><p>'+esc(e.criteria)+'</p>':''}<h3>Interpretation boundary</h3><p>This is a dated annotation. A before/after coincidence does not establish a causal effect. Compare observation coverage and matched periods before drawing a conclusion.</p><button class="primary" id="drawer-experiment">Start an observational follow-up</button>`;}
else if(id==='explain'){heading='Explain this change';eyebrow='Evidence-first · local example';content=`<p>This is a deterministic explanation preview, with no AI service connected.</p><h3>Current question</h3><p>${appName()} · ${S.market} · ${span(w)} · ${S.screen==='keywords'?selected().length+' selected keywords':S.metric}</p><h3>Facts in scope</h3>${S.screen==='keywords'?keywords().filter(r=>selected().includes(r.id)).map(r=>{const c=A.rankSummary(r.points,w),b=p?A.rankSummary(r.points,p):null;return `<p><strong>${esc(r.name)}</strong><br>Mean observed rank ${num(c.mean,1)}${b?' vs '+num(b.mean,1):''}; ${c.collected}/${c.expected} days collected. ${c.legacy?'Legacy method excluded.':''}</p>`;}).join(''):'<p>Daily report rows, native currency EUR and the selected attribution definition. Provisional days are excluded in the delay scenario.</p>'}<h3>What remains uncertain</h3><p>The sample cannot establish causality, incremental lift, or a paid-to-organic effect. Missing observations and method boundaries limit comparisons.</p><h3>A useful next check</h3><p>Inspect the aligned daily observations around the metadata annotation. Confirm the source context before forming a hypothesis.</p><button class="primary" id="drawer-experiment">Record an experiment hypothesis</button>`;}
else if(id==='diagnostics'){heading='Collection diagnostic';content='<p>Sample job · rank-observation-fixture</p><dl><dt>Scope</dt><dd>POIS / DE / iPhone</dd><dt>Attempt</dt><dd>4 Oct · 08:00 UTC</dd><dt>Outcome</dt><dd>Failed · upstream timeout</dd><dt>Next recovery</dt><dd>Retry eligible collection</dd></dl><p>No retry runs from this prototype. Retain the failed observation record; a replacement must preserve provenance.</p>';}
else{heading='Paid search evidence';content='<p>Reported-query and targeting-keyword identities remain distinct. EUR amounts, attribution type and date boundaries stay attached to every row.</p><h3>Suppression & coverage</h3><p>Term rows represent 93% of this synthetic parent. Remaining rows are suppressed or unreported; they are not inferred as zero.</p><button class="primary" id="drawer-experiment">Record an investigation</button>';}
$('#overlay').innerHTML=`<div class="sheet-backdrop" data-close></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(heading)}"><header class="drawer-head"><div><div class="eyebrow">${eyebrow}</div><h2>${esc(heading)}</h2></div><button class="close-button" data-close aria-label="Close detail">×</button></header>${content}</aside>`;document.querySelectorAll('[data-close]').forEach(e=>e.onclick=closeOverlay);if($('#drawer-experiment'))$('#drawer-experiment').onclick=()=>modal('experiment');if($('#save-note'))$('#save-note').onclick=()=>{save('note-'+id.split(':')[1],$('#keyword-note').value);toast('Note saved in this browser only.');};$('.drawer .close-button').focus();}
function closeOverlay(){if(S.drawer){S.drawer='';history.replaceState({},'',url());}$('#overlay').innerHTML='';modalType=null;lastFocus?.isConnected&&lastFocus.focus();}
function modal(type){lastFocus=document.activeElement;modalType=type;const w=windowAll(),p=comparator()||A.prior(w);let title='',body='',footer='';if(type==='range'){title='Analyze a chart range';body=`<div class="form-grid"><label>Selected start<input type="date" name="brushStart" value="${A.shift(w.end,-6)}" min="${w.start}" max="${w.end}" required></label><label>Selected end<input type="date" name="brushEnd" value="${w.end}" min="${w.start}" max="${w.end}" required></label><p class="footnote full">The table, summaries and export will use these dates. Clear the selection to restore the whole reporting window.</p></div>`;footer='<button type="submit" class="primary">Analyze selected range</button>';}if(type==='dates'){title='Choose comparable periods';body=`<div class="form-grid"><label>Current start<input name="start" type="date" min="2026-04-15" max="${F.END}" value="${w.start}" required></label><label>Current end<input name="end" type="date" max="${F.END}" value="${w.end}" required></label><label>Comparison start<input name="compareStart" type="date" value="${p.start}" required></label><label>Comparison end<input name="compareEnd" type="date" max="${F.END}" value="${p.end}" required></label><p class="footnote full">Actual dates stay visible. Rank summaries use only comparable vendor observations; unequal windows are explicitly labeled.</p></div>`;footer='<button class="primary" type="submit">Apply periods</button>';}
if(type==='save'){title='Save this analysis';body='<label>View name<input name="name" required maxlength="90" value="'+esc(appName()+' — '+S.market+' — '+S.range+' days — '+names[S.screen])+'"></label><p class="footnote" style="margin-top:14px">Stored in this browser. Includes filters, plotted keywords, dates and comparison. No server is contacted.</p>';footer='<button class="primary" type="submit">Save local view</button>';}
if(type==='saved'){title='Your saved views';const views=stored('views',[]);body=views.length?views.map((v,i)=>`<button type="button" class="saved-link" data-saved="${i}">${esc(v.name)} ↗</button>`).join(''):'<p class="muted">No local views yet. Save a filtered analysis to return to it quickly.</p>';}
if(type==='experiment'){title='Start from this evidence';body=`<div class="form-grid"><p class="footnote full">${appName()} · ${S.market} · ${span(windowNow())} · ${S.screen==='keywords'?'vendor rank observations':S.metric+' report rows'} · sample context prefilled</p><label class="full">Title<input name="name" required placeholder="What do you want to learn?" maxlength="100"></label><label class="full">Hypothesis<textarea name="hypothesis" required placeholder="If we change…, we expect…"></textarea></label><label class="full">Success criterion<input name="criteria" required placeholder="Metric, direction, threshold and evaluation window"></label><label>Study type<select name="type"><option>Observational</option><option>Controlled Apple PPO · plan only</option></select></label><label>Evaluation end<input name="evaluationEnd" type="date" value="2026-10-25" required></label><p class="footnote full">Creates a local planning note. No experiment, metadata or advertising change is launched.</p></div>`;footer='<button class="primary" type="submit">Save local experiment note</button>';}
if(type==='command'){title='Jump to an analysis';body=Object.entries(names).map(([k,v])=>`<button type="button" class="command-item" data-command="${k}">${v}<small>Keep current context ↵</small></button>`).join('')+'<p class="footnote">Keyboard: Tab to choose · Enter to open · Escape to close</p>';}
$('#overlay').innerHTML=`<div class="dialog-backdrop"><form class="modal" role="dialog" aria-modal="true" aria-label="${title}" id="modal-form"><header class="modal-head"><h2>${title}</h2><button class="close-button" data-close type="button" aria-label="Close dialog">×</button></header>${body}<div class="form-error" aria-live="polite"></div><footer>${footer}</footer></form></div>`;$('[data-close]').onclick=closeOverlay;$('#modal-form').onsubmit=ev=>{ev.preventDefault();const form=Object.fromEntries(new FormData(ev.target));if(type==='range'){if(form.brushStart>form.brushEnd){$('.form-error').textContent='Choose a start before the end.';return;}closeOverlay();change(form);}if(type==='dates'){if(form.start>form.end||form.compareStart>form.compareEnd){$('.form-error').textContent='Each period must start before it ends.';return;}closeOverlay();change({...form,range:'custom',compare:'custom',brushStart:'',brushEnd:''});}if(type==='save'){save('views',[...stored('views',[]),{name:form.name,state:{...S,drawer:''}}]);closeOverlay();toast('View saved locally with selected series and comparison.');}if(type==='experiment'){save('experiments',[...localEvents(),{...form,date:windowNow().end,status:'Planned',detail:form.hypothesis,context:{...S}}]);closeOverlay();change({screen:'experiments',drawer:''});toast('Planning note saved locally. Nothing was launched.');}};document.querySelectorAll('[data-command]').forEach(e=>e.onclick=()=>{closeOverlay();change({screen:e.dataset.command,drawer:'',query:'',metric:e.dataset.command==='ads'?'spend':'downloads'});});document.querySelectorAll('[data-saved]').forEach(e=>e.onclick=()=>{const state=stored('views',[])[+e.dataset.saved].state;closeOverlay();S={...defaults,...state};history.pushState({},'',url());render();});const submitButton=$('#modal-form [type=submit]');if(submitButton)submitButton.onclick=e=>{e.preventDefault();$('#modal-form').requestSubmit();};$('.modal input, .modal .command-item, .modal .saved-link, .modal .close-button')?.focus();}
function exportCSV(){const w=windowNow(),p=comparator(),base={sample_data:true,app:appName(),storefront:S.market,requested_locale:S.market==='DE'?'de-DE':'en-US',device:S.device,period_start:w.start,period_end:w.end,comparator_start:p?.start||'',comparator_end:p?.end||'',table_filter:S.query,sort:S.screen==='ads'?'spend:'+(S.adsSort||'desc'):S.sort,selected_series:S.screen==='keywords'?S.selected:(S.screen==='ads'?adsRows():appRows()).filter(r=>!(S.hidden||'').split(',').includes(r.id)).map(r=>r.id).join(','),hidden_series:S.hidden||''};let rows;if(S.screen==='keywords'){rows=filteredKeywords().filter(r=>selected().includes(r.id)).flatMap(r=>A.inWindow(r.points,w).map(o=>({...base,keyword:r.name,date:o.date,position:o.rank,status:o.status,method:o.method,provider:o.provider,depth:o.depth,coverage:A.rankSummary(r.points,w).coverage,definition:'Observed vendor rank only; absent is not rank101; missing is not zero'})));}else{rows=(S.screen==='ads'?adsRows():appRows()).filter(r=>!(S.hidden||'').split(',').includes(r.id)).flatMap(r=>A.inWindow(r.points,matureWindow(w)).map(o=>({...base,name:r.name,level:S.screen==='ads'?S.level:'app',date:o.date,downloads:S.screen==='ads'?'':o.downloads,spend:o.spend,currency:'EUR',taps:o.taps,attributed_downloads:S.scenario==='ambiguous'?'':o.installs,attribution:S.attribution,timezone:'Europe/Berlin',status:o.status,method:o.method,definition:'Spend: native EUR; CPA: sum spend / sum selected-attribution downloads; term suppression may apply'})));}if(!rows.length){toast('Select a keyword in the filtered scope before exporting.');return;}const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([A.csv(rows)],{type:'text/csv;charset=utf-8'}));link.download='kopa-SAMPLE-'+S.screen+'-'+w.start+'-'+w.end+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),2000);toast('Exported the selected sample scope and source definitions.');}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-modal]');if(trigger){e.preventDefault();modal(trigger.getAttribute('data-modal'));}const actionTrigger=e.target.closest('[data-action]');if(actionTrigger){e.preventDefault();action(actionTrigger.getAttribute('data-action'));}const event=e.target.closest('.event-controls [data-event]');if(event){e.preventDefault();openDrawer('event:'+event.getAttribute('data-event'));}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();modal('command');}if(e.key==='Escape')closeOverlay();if(e.key==='Tab'&&$('#overlay [role=dialog]')){const controls=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled);if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});window.addEventListener('popstate',()=>{read();render();});read();render();
})();
